  "Recorded collision evidence": "Dokumentierte Kollisionsnachweise",
  "A complete report is recorded for a different STL selection; it does not apply to this file.": "Ein vollständiger Bericht ist für eine andere STL-Auswahl dokumentiert; er gilt nicht für diese Datei.",
  "Only a legacy physics summary is recorded. No complete collision report is available for this selection.": "Es ist nur eine ältere Physikzusammenfassung dokumentiert. Für diese Auswahl liegt kein vollständiger Kollisionsbericht vor.",
  "No complete collision report is recorded for this selection.": "Für diese Auswahl ist kein vollständiger Kollisionsbericht dokumentiert.",
  "Legacy summary: {0} {1}; {2}; reported qualified: {3}.": "Ältere Zusammenfassung: {0} {1}; {2}; als qualifiziert gemeldet: {3}.",
  "Browsing and insertion do not run collision qualification.": "Beim Durchsuchen und Einfügen wird keine Kollisionsqualifikation ausgeführt.",
  "Serialized curator evidence only. Recorded metadata is not a reusable runtime collision proof or a certification of collision safety, printability or mechanical accuracy.": "Nur gespeicherte Nachweise der Kuratierung. Gespeicherte Metadaten sind weder ein wiederverwendbarer Laufzeit-Kollisionsnachweis noch eine Zertifizierung von Kollisionssicherheit, Druckbarkeit oder mechanischer Genauigkeit.",
  "Runtime collisions require fresh immutable proofs. Changed bytes, conversion, geometry or toolchain require requalification.": "Laufzeitkollisionen benötigen neue unveränderliche Nachweise. Geänderte Bytes, Umrechnung, Geometrie oder Werkzeugkette erfordern eine erneute Qualifikation.",
  "Inspect complete recorded collision report": "Vollständigen dokumentierten Kollisionsbericht ansehen",
