  "Native check: {0} build; {1} rigid step of {2} s; no ground.": "Native Prüfung: Build {0}; {1} Starrkörperschritt von {2} s; ohne Boden.",
  "No ground settling, cavity clearance, contacts, mechanisms, elasticity, printability or manufacturing accuracy were tested. Native capacity/error telemetry is unavailable.": "Bodenkontakt, Hohlraumfreiheit, Kontakte, Mechanismen, Elastizität, Druckbarkeit und Fertigungsgenauigkeit wurden nicht geprüft. Native Kapazitäts-/Fehlertelemetrie ist nicht verfügbar.",
