  "Start with X, Y. Use @dX, dY to enter a point relative to the previous one.": "Beginne mit X, Y. Verwende @dX, dY für einen Punkt relativ zum vorherigen.",
  "Enter the first point as absolute X, Y coordinates.": "Gib den ersten Punkt in absoluten X-, Y-Koordinaten ein.",
  "Drag the white handles or type exact dimensions.": "Ziehe an den weißen Griffen oder gib genaue Maße ein.",
  "Export sketch as DXF": "Skizze als DXF exportieren",
  "DXF export requires an original sketch extrusion.": "Der DXF-Export benötigt eine eigene Skizzenextrusion.",
  "Export the 2D profile at sketch dimensions in millimetres.": "Exportiert das 2D-Profil mit den Skizzenmaßen in Millimetern.",
  "Choose a profile and its plane. XY is horizontal. XZ and YZ are upright.": "Wähle ein Profil und seine Ebene. XY ist waagerecht. XZ und YZ sind senkrecht.",
  "Type dimensions or drag the preview handles. For an outline, enter one X, Y point per line. The last point connects to the first.": "Gib Maße ein oder ziehe die Griffe. Gib für einen Umriss je Zeile einen X-, Y-Punkt ein. Der letzte Punkt wird mit dem ersten verbunden.",
  "Circle center X, Y (mm)": "Kreismittelpunkt X, Y (mm)",
  "Outline points X, Y (mm)": "Umrisspunkte X, Y (mm)",
  "Enter coordinates as X, Y in millimetres.": "Gib die Koordinaten als X, Y in Millimetern ein.",
  "An outline needs 3–256 finite points within 100000 mm of the sketch origin.": "Ein Umriss benötigt 3–256 endliche Punkte im Koordinatenbereich bis 100000 mm.",
  "Outline edges must form one closed loop without crossings or overlaps.": "Die Kanten müssen einen geschlossenen Umriss ohne Kreuzungen oder Überlappungen bilden.",
  "Circle center must be within 100000 mm of the sketch origin.": "Die Koordinaten des Kreismittelpunkts dürfen höchstens 100000 mm vom Ursprung abweichen.",
  "The source plane was unfolded into the selected sketch plane at actual size.": "Die Quellebene wurde in Originalgröße in die gewählte Skizzenebene übertragen.",
  "DXF extrusion directions must be finite and nonzero.": "DXF-Extrusionsrichtungen müssen endlich und ungleich null sein.",
  "Select DXF entities on one plane. The selected geometry is not coplanar.": "Wähle DXF-Objekte auf einer Ebene. Die gewählte Geometrie liegt nicht in einer gemeinsamen Ebene.",
