  "Return a complete history-inclusive .bcad archive as base64; large projects use the configured project file instead.": "Ein vollständiges .bcad-Archiv mit Verlauf als base64 zurückgeben; bei großen Projekten die konfigurierte Projektdatei verwenden.",
  "Return printable binary STL as base64 from current evaluated geometry.": "Druckbare binäre STL-Datei aus der aktuell berechneten Geometrie als base64 zurückgeben.",
