  "Add a shape, then edit its dimensions under Properties. Dimensions and positions use millimetres, with Z pointing up.": "Fügen Sie eine Form hinzu und bearbeiten Sie ihre Maße unter Eigenschaften. Maße und Positionen werden in Millimetern angegeben; Z zeigt nach oben.",
  "Select multiple bodies with their checkboxes, Shift-click, or a long press. For Subtract, select the base first, then its cutters. Source shapes remain editable under the operation.": "Wählen Sie mehrere Körper über ihre Kontrollkästchen, mit Umschalt-Klick oder langem Drücken aus. Wählen Sie für Subtrahieren zuerst den Grundkörper und dann die Schnittkörper. Die Ausgangsformen bleiben unter der Operation bearbeitbar.",
  "Use the view cube for Top, Front and Right views. The view menu also offers Back, Left and Bottom. Home restores the 3D angle; Fit frames your model. The left rail includes zoom, orthographic projection, workplane visibility and touch multi-select.": "Verwenden Sie den Ansichtswürfel für die Ansichten Oben, Vorne und Rechts. Das Ansichtsmenü bietet auch Hinten, Links und Unten. Startansicht stellt den 3D-Winkel wieder her; Einpassen zeigt das ganze Modell. Die linke Leiste bietet Zoom, orthografische Projektion, Sichtbarkeit der Arbeitsebene und Touch-Mehrfachauswahl.",
